import fnmatch

class Job:
    def __init__(self, jid, cmd_str, procs):
        self.jid = jid
        self.cmd_str = cmd_str
        self.procs = procs  # list of Popen or None for builtins

class Shell:
    def __init__(self):
        self.vars = {}
        # init from environment
        for k,v in os.environ.items():
            self.vars[k] = v
        self.exported = set()
        # mark PATH etc as exported? In shell, exported vars are those from env + export builtin
        # For simplicity, all initial vars are exported (in env)
        for k in os.environ.keys():
            self.exported.add(k)
        self.functions = {}
        self.aliases = {}
        self.last_status = 0
        self.pid = os.getpid()
        self.jobs = []  # list of Job
        self.next_jid = 1
        self.dir_stack = []
        self.oldpwd = None
        self.pos_params = []  # for functions; top-level empty
        self.read_prompt = None
        # IFS: None means unset (default whitespace)
        # We'll check self.vars for IFS
        self.loop_break = None  # for break/continue handling in for loops
        self.func_depth = 0
        self.in_function = False

    def get_ifs(self):
        if "IFS" in self.vars:
            return self.vars["IFS"]
        else:
            return None  # unset

    def is_exported(self, name):
        return name in self.exported

    def set_var(self, name, value, export=False):
        self.vars[name] = value
        if export or name in self.exported:
            self.exported.add(name)
            os.environ[name] = value
        # if not exported, remove from os.environ? Actually unset from env if not exported?
        # For shell vars not exported, they should not be in env. But initial vars are exported.
        # When we set non-exported, ensure not in os.environ unless exported.
        if name not in self.exported:
            if name in os.environ:
                # keep? Actually if var was previously exported and now set without export, should it stay exported?
                # In shell, VAR=val without export keeps export flag if previously exported.
                # Our set_var with export=False but name in exported stays exported (handled above).
                # If not in exported, remove from env.
                try:
                    del os.environ[name]
                except: pass
        else:
            os.environ[name] = value

    def unset_var(self, name):
        if name in self.vars:
            del self.vars[name]
        if name in self.exported:
            self.exported.remove(name)
        if name in os.environ:
            try:
                del os.environ[name]
            except: pass
        if name in self.functions:
            del self.functions[name]

    def get_var(self, name):
        return self.vars.get(name, "")

